#define DMX_GRAPH_NO_MAIN
#include "dmx_graph.cpp"
#include "session_frame_rate_candidate.h"
#include <limits>
Attribute& field(Graph&g,uint32_t id,const char*name){for(auto&a:g.elements.at(id).attributes)if(g.strings[a.name]==name)return a;throw std::runtime_error("test field missing");}
void setFloat(Attribute&a,float f){std::memcpy(a.values.at(0).wire.data(),&f,4);}
void check(bool ok){if(!ok)throw std::runtime_error("session rate assertion");}
int main(){try{size_t rejected=0;for(auto path:{"work/roundtrip-11.dmx","work/roundtrip-139.dmx"}){auto baseline=loadGraph(path);auto active=hierarchyRefs(baseline,baseline.elements.at(0),"activeClip",1);check(active.size()==1);auto root=active[0];auto settings=hierarchyRefs(baseline,baseline.elements[0],"settings",1).at(0);auto render=hierarchyRefs(baseline,baseline.elements[settings],"renderSettings",1).at(0);auto expected=sessionFrameRateCandidate(baseline,root);auto g=baseline;size_t lights=0;for(auto&e:g.elements)if(g.strings[e.type]=="DmeProjectedLight")for(auto&a:e.attributes)if(g.strings[a.name]=="frameRate"){setFloat(a,1.f);++lights;}check(sessionFrameRateCandidate(g,root)==expected);std::cout<<"fixture="<<path<<" packed="<<expected<<" unrelated_lights_changed="<<lights<<'\n';auto reject=[&](auto mutate){auto bad=baseline;mutate(bad);bool failed=false;try{sessionFrameRateCandidate(bad,root);}catch(const std::exception&){failed=true;}check(failed);++rejected;};for(float value:{0.f,-1.f,.1f,std::numeric_limits<float>::infinity(),std::numeric_limits<float>::quiet_NaN()})reject([&](Graph&bad){setFloat(field(bad,render,"frameRate"),value);});reject([&](Graph&bad){bad.elements.push_back(bad.elements[0]);});reject([&](Graph&bad){field(bad,settings,"renderSettings").values[0].reference=0xffffffff;});reject([&](Graph&bad){field(bad,render,"frameRate").type=2;});reject([&](Graph&bad){auto a=field(bad,render,"frameRate");bad.elements[render].attributes.push_back(a);});}check(rejected==18);std::cout<<"session rate selection passed fixtures=2 malformed_cases_rejected="<<rejected<<'\n';return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
